-- 000500_studio_jobs_adr088_ai_columns.up.sql
-- Add ADR-088 universal AI content generation columns to the studio_jobs table.
-- All admin-managed content tables in §§79–101 must carry ai_generated,
-- ai_model, hitl_reviewed_by, ai_generated_at, hitl_reviewed_at.
-- studio_jobs is the AI Content Studio job queue (§75) — every row is
-- AI-generated by definition, but the columns are required for ADR-088
-- conformance and to track which model generated the draft and who reviewed it.
--
-- Ref: japaconnect-engineering/adr/ADR-088-destination-wiki.md (universal AI content generation)
--      japaconnect-engineering/sections/75-ai-content-studio.md
--      japaconnect-engineering/audit/ai-audit.md (BUG-005)

BEGIN;

ALTER TABLE studio_jobs
    ADD COLUMN IF NOT EXISTS ai_generated      boolean NOT NULL DEFAULT true,
    ADD COLUMN IF NOT EXISTS ai_model          text,
    ADD COLUMN IF NOT EXISTS ai_generated_at   timestamptz,
    ADD COLUMN IF NOT EXISTS hitl_reviewed_by  uuid REFERENCES users(id) ON DELETE SET NULL,
    ADD COLUMN IF NOT EXISTS hitl_reviewed_at  timestamptz;

COMMIT;
